// Des: Local fake Facebook site for tests (loopback, random port)
// Flo: listen 127.0.0.1:0 > per-connection thread > route path to a fixture page > /_rec stores what the page did > tests read records
// I/O: HTTP GET (browser) > fixture HTML; records "kind|text" for assertions
// ===================================================================
const std = @import("std"); const net = std.Io.net; const fixt = @import("te-fixt-html.zig");
const CF = .{ .slot = 64, .slen = 256 };
pub const Mock = struct { serv: net.Server, iozz: std.Io, port: u16, hits: std.atomic.Value(u32) = .init(0), actv: std.atomic.Value(u32) = .init(0), stop: std.atomic.Value(bool) = .init(false), thrd: ?std.Thread = null, rcnt: std.atomic.Value(u32) = .init(0), rbuf: [CF.slot][CF.slen]u8 = undefined, rlen: [CF.slot]std.atomic.Value(u32) = @splat(.init(0)),
pub fn start(self: *Mock, iozz: std.Io) !void { var addr = try net.IpAddress.parse("127.0.0.1", 0); const serv = try addr.listen(iozz, .{ .reuse_address = true }); self.* = .{ .serv = serv, .iozz = iozz, .port = serv.socket.address.getPort() }; self.thrd = try std.Thread.spawn(.{}, loop, .{self}); }
pub fn halt(self: *Mock) void { self.stop.store(true, .release); if (net.IpAddress.parse("127.0.0.1", self.port)) |addr| { if (addr.connect(self.iozz, .{ .mode = .stream })) |strm| strm.close(self.iozz) else |_| {} } else |_| {} if (self.thrd) |thrd| thrd.join(); var wtz: u32 = 0; while (self.actv.load(.acquire) > 0 and wtz < 300) : (wtz += 1) std.Io.sleep(self.iozz, .fromMilliseconds(10), .awake) catch {}; self.serv.deinit(self.iozz); }
pub fn urlOf(self: *Mock, buff: []u8, path: []const u8) []const u8 { return std.fmt.bufPrint(buff, "http://127.0.0.1:{d}{s}", .{ self.port, path }) catch ""; }
pub fn recCnt(self: *Mock) usize { return @min(self.rcnt.load(.acquire), CF.slot); }
pub fn recAt(self: *Mock, idx: usize) []const u8 { return self.rbuf[idx][0..self.rlen[idx].load(.acquire)]; }
pub fn recFind(self: *Mock, kind: []const u8) ?[]const u8 { var idx: usize = 0; while (idx < self.recCnt()) : (idx += 1) { const rec = self.recAt(idx); if (rec.len > kind.len and std.mem.startsWith(u8, rec, kind) and rec[kind.len] == '|') return rec[kind.len + 1 ..]; } return null; }
pub fn recNum(self: *Mock, kind: []const u8) usize { var cnt: usize = 0; var idx: usize = 0; while (idx < self.recCnt()) : (idx += 1) { const rec = self.recAt(idx); if (rec.len > kind.len and std.mem.startsWith(u8, rec, kind) and rec[kind.len] == '|') cnt += 1; } return cnt; } };
fn conn(self: *Mock, strm: net.Stream) void { defer { strm.close(self.iozz); _ = self.actv.fetchSub(1, .release); } serve(self, strm) catch {}; }
fn loop(self: *Mock) void { while (!self.stop.load(.acquire)) { const strm = self.serv.accept(self.iozz) catch continue; if (self.stop.load(.acquire)) { strm.close(self.iozz); return; } _ = self.hits.fetchAdd(1, .monotonic); _ = self.actv.fetchAdd(1, .acq_rel); const thr = std.Thread.spawn(.{}, conn, .{ self, strm }) catch { conn(self, strm); continue; }; thr.detach(); } }
fn unesc(dst: []u8, src: []const u8) []u8 { var out: usize = 0; var idx: usize = 0; while (idx < src.len and out < dst.len) { if (src[idx] == '%' and idx + 2 < src.len) { if (std.fmt.parseInt(u8, src[idx + 1 .. idx + 3], 16)) |bytz| { dst[out] = bytz; out += 1; idx += 3; continue; } else |_| {} } dst[out] = if (src[idx] == '+') ' ' else src[idx]; out += 1; idx += 1; } return dst[0..out]; }
fn recStore(self: *Mock, kind: []const u8, text: []const u8) void { const idx = self.rcnt.fetchAdd(1, .acq_rel); if (idx >= CF.slot) return; var tmp: [CF.slen]u8 = undefined; const lenz = if (std.fmt.bufPrint(&tmp, "{s}|{s}", .{ kind, text })) |wr| wr.len else |_| 0; @memcpy(self.rbuf[idx][0..lenz], tmp[0..lenz]); self.rlen[idx].store(@intCast(lenz), .release); }
fn qryGet(qry: []const u8, key: []const u8) []const u8 { var itr = std.mem.splitScalar(u8, qry, '&'); while (itr.next()) |pair| { const eql = std.mem.findScalar(u8, pair, '=') orelse continue; if (std.mem.eql(u8, pair[0..eql], key)) return pair[eql + 1 ..]; } return ""; }
fn pageFor(path: []const u8) ?[]const u8 { if (std.mem.eql(u8, path, "/")) return fixt.HOME; if (std.mem.startsWith(u8, path, "/groups/")) return fixt.GROUP; if (std.mem.startsWith(u8, path, "/profile/")) return fixt.PROFILE; if (std.mem.startsWith(u8, path, "/messages/t/")) return fixt.DMSG; if (std.mem.eql(u8, path, "/notifications")) return fixt.NOTI; if (std.mem.startsWith(u8, path, "/marketplace/create")) return fixt.MCRE; if (std.mem.startsWith(u8, path, "/marketplace/you/selling")) return fixt.MSEL; if (std.mem.startsWith(u8, path, "/checkpoint")) return fixt.CHKP; if (std.mem.startsWith(u8, path, "/login")) return fixt.LOGI; if (std.mem.eql(u8, path, "/blocked")) return fixt.BLOK; return null; }
fn serve(self: *Mock, strm: net.Stream) !void { var rbuf: [4096]u8 = undefined; var rdr = strm.reader(self.iozz, &rbuf); const rdi = &rdr.interface; const first = try rdi.takeDelimiterInclusive('\n'); var clen: usize = 0; while (true) { const line = try rdi.takeDelimiterInclusive('\n'); if (line.len <= 2) break; if (std.ascii.startsWithIgnoreCase(line, "content-length:")) clen = std.fmt.parseInt(usize, std.mem.trim(u8, line[15..], " \r\n"), 10) catch 0; } if (clen > 0) _ = try rdi.take(@min(clen, 4096)); var parts = std.mem.splitScalar(u8, first, ' '); _ = parts.next(); const rawp = parts.next() orelse "/"; const qix = std.mem.findScalar(u8, rawp, '?'); const path = if (qix) |ix| rawp[0..ix] else rawp; const qry = if (qix) |ix| rawp[ix + 1 ..] else ""; var wbuf: [4096]u8 = undefined; var wrtr = strm.writer(self.iozz, &wbuf); const outp = &wrtr.interface;
if (std.mem.eql(u8, path, "/_rec")) { var kb: [32]u8 = undefined; var tb: [CF.slen]u8 = undefined; recStore(self, unesc(&kb, qryGet(qry, "k")), unesc(&tb, qryGet(qry, "t"))); try outp.writeAll("HTTP/1.1 204 No Content\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); } else if (std.mem.eql(u8, path, "/completion")) { const jsn = "{\"content\":\" Sure, happy to help! \"}"; try outp.print("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {d}\r\nConnection: close\r\n\r\n", .{jsn.len}); try outp.writeAll(jsn); } else if (pageFor(path)) |body| { try outp.print("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {d}\r\nConnection: close\r\n\r\n", .{body.len}); try outp.writeAll(body); } else { try outp.writeAll("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"); }
try outp.flush(); }
